TEST_F(CrestApiFsCoveringStartTest, OutOfOrderInsertionCoveringStillCorrect) {
  CrestApiFs api(true, m_root);
  // Inserted out of ascending order: 0, then 300, then 100, then 200.
  createTagWithIovs(api, {0, 300, 100, 200});

  IovSetDto page = api.selectIovs(m_tagname, 150, static_cast<uint64_t>(-1), 0,
                                  1000, 0, "id.since:ASC");

  // Covering IOV for since=150 is 100 (greatest since <= 150), not 0.
  EXPECT_EQ(sincesOf(page), (std::vector<uint64_t>{100, 200, 300}));
}
